using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TechnifyERP.Application.CourseChanges;
namespace TechnifyERP.Areas.Admin;
[Area("Admin"),Authorize(Roles="SuperAdmin")]public sealed class CourseChangesController(ICourseChangeService service):Controller{public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetAllAsync(ct));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Review(int id,bool approve,string? remarks,CancellationToken ct){var r=await service.ReviewAsync(id,approve,remarks,ct);TempData[r==CourseChangeActionResult.Success?"SuccessMessage":"ErrorMessage"]=r==CourseChangeActionResult.Success?(approve?"Course change approve ho gaya; new fee record create ho gaya.":"Course change reject ho gaya."):"Request review nahi ho saki.";return RedirectToAction(nameof(Index));}}
